class StepContext:
    """Per-scenario state available to op handlers and expectation checkers."""

    def __init__(self, scenario: Mapping[str, Any], target: Any, variables: dict[str, Any]):
        self.scenario = scenario
        self.target = target
        self.variables = variables
        self._loop: asyncio.AbstractEventLoop | None = None

    def substitute(self, value: Any) -> Any:
        """Replace ``${name}`` in strings, recursively in lists and in dict keys and values.

        A string value that is exactly one ``${name}`` keeps the variable's type.
        """
        if isinstance(value, str):
            whole = _VAR.fullmatch(value)
            if whole and whole.group(1) in self.variables:
                return self.variables[whole.group(1)]
            return _VAR.sub(lambda m: str(self.variables.get(m.group(1), m.group(0))), value)
        if isinstance(value, list):
            return [self.substitute(v) for v in value]
        if isinstance(value, dict):
            return {self._substitute_key(k): self.substitute(v) for k, v in value.items()}
        return value

    def _substitute_key(self, key: Any) -> Any:
        """Keys are always strings, so every ``${name}`` is replaced textually."""
        if not isinstance(key, str):
            return key
        return _VAR.sub(lambda m: str(self.variables.get(m.group(1), m.group(0))), key)

    def resolve(self, value: Any) -> Any:
        """Run an awaitable on the scenario's private event loop; return other values as is."""
        if not inspect.isawaitable(value):
            return value
        if self._loop is None:
            self._loop = asyncio.new_event_loop()
        return self._loop.run_until_complete(_await(value))

    def close(self) -> None:
        if self._loop is not None:
            self._loop.run_until_complete(self._loop.shutdown_asyncgens())
            self._loop.close()
            self._loop = None


async def _await(value: Any) -> Any:
    return await value


@dataclasses.dataclass
class StepResult:
    index: int
    op: str
    status: str  # "passed" | "failed" | "skipped"
    message: str = ""


@dataclasses.dataclass
class ScenarioResult:
    id: str
    category: str
    status: str  # "passed" | "failed" | "skipped"
    reason: str = ""
    steps: list[StepResult] = dataclasses.field(default_factory=list)
    duration_s: float = 0.0


@dataclasses.dataclass
class ConformanceReport:
    results: list[ScenarioResult] = dataclasses.field(default_factory=list)

    def _with(self, status: str) -> list[ScenarioResult]:
        return [r for r in self.results if r.status == status]

    @property
    def passed(self) -> list[ScenarioResult]:
        return self._with("passed")

    @property
    def failed(self) -> list[ScenarioResult]:
        return self._with("failed")

    @property
    def skipped(self) -> list[ScenarioResult]:
        return self._with("skipped")

    @property
    def ok(self) -> bool:
        return not self.failed

    def to_dict(self) -> dict[str, Any]:
        return {
            "passed": len(self.passed),
            "failed": len(self.failed),
            "skipped": len(self.skipped),
            "results": [dataclasses.asdict(r) for r in self.results],
        }

    def summary(self) -> str:
        lines = [
            f"conformance: {len(self.passed)} passed, {len(self.failed)} failed, "
            f"{len(self.skipped)} skipped"
        ]
        for r in self.results:
            line = f"  {r.status.upper():7} {r.id}"
            if r.reason:
                line += f" — {r.reason}"
            lines.append(line)
        return "\n".join(lines)

    def raise_on_failure(self) -> None:
        if self.failed:
            raise AssertionError(self.summary())


# --------------------------------------------------------------------------- loading


def find_scenarios_dir(start: Path | None = None) -> Path:
    """``$GROW_CONFORMANCE_DIR`` or the nearest ``conformance/scenarios`` above ``start``/cwd."""
    env = os.environ.get(SCENARIOS_ENV)
    if env:
        return Path(env)
    for base in (start or Path.cwd(), Path(__file__).resolve()):
        for parent in (base, *base.parents):
            candidate = parent / "conformance" / "scenarios"
            if candidate.is_dir():
                return candidate
    raise FileNotFoundError("conformance/scenarios not found; set GROW_CONFORMANCE_DIR")


def load_scenarios(
    directory: Path | str | None = None, categories: Iterable[str] | None = None
) -> list[dict[str, Any]]:
    """Scenarios sorted by id, optionally limited to ``categories``."""
    folder = Path(directory) if directory is not None else find_scenarios_dir()
    wanted = set(categories) if categories is not None else None
    scenarios = []
    for path in sorted(folder.glob("*.json")):
        doc = json.loads(path.read_text(encoding="utf-8"))
        if wanted is None or doc.get("category") in wanted:
            scenarios.append(doc)
    return sorted(scenarios, key=lambda d: str(d.get("id")))


# --------------------------------------------------------------------------- comparison


def _camel(name: str) -> str:
    head, *rest = name.split("_")
    return head + "".join(p[:1].upper() + p[1:] for p in rest)


def to_jsonable(value: Any) -> Any:
    """JSON-like view of a result: dataclasses → dicts (camelCase keys), enums → values,
    datetimes → ISO strings, secret values → revealed text."""
    reveal = getattr(value, "reveal", None)
    if callable(reveal) and type(value).__name__ == "SecretValue":
        try:
            return reveal()
        except ServiceError:
            return "<binary>"
    if dataclasses.is_dataclass(value) and not isinstance(value, type):
        return {
            _camel(f.name): to_jsonable(getattr(value, f.name)) for f in dataclasses.fields(value)
        }
    if isinstance(value, enum.Enum):
        return to_jsonable(value.value)
    if isinstance(value, Mapping):
        return {str(k): to_jsonable(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set, frozenset)):
        return [to_jsonable(v) for v in value]
    if isinstance(value, (_dt.datetime, _dt.date)):
        return value.isoformat()
    return value


def _subset_equal(actual: Any, expected: Any) -> bool:
    if isinstance(expected, dict):
        if not isinstance(actual, dict):
            return False
        return all(k in actual and _subset_equal(actual[k], v) for k, v in expected.items())
    if isinstance(expected, list):
        return (
            isinstance(actual, list)
            and len(actual) == len(expected)
            and all(_subset_equal(a, e) for a, e in zip(actual, expected, strict=True))
        )
    if isinstance(expected, bool) or isinstance(actual, bool):
        return type(expected) is type(actual) and expected == actual
    return bool(actual == expected)


def _size(result: Any) -> int | None:
    spans = getattr(result, "spans", None)
    if spans is not None and not isinstance(result, Mapping):
        return len(spans)
    if isinstance(result, Mapping) and "spans" in result and isinstance(result["spans"], list):
        return len(result["spans"])
    try:
        return len(result)
    except TypeError:
        return None


def _forms(result: Any) -> list[str]:
    forms = [str(result), repr(result)]
    with contextlib.suppress(TypeError, ValueError):
        forms.append(json.dumps(result, default=str))
    return forms


def _check_reveal(result: Any, expected: Any, ctx: StepContext) -> str | None:
    if result is None or not hasattr(result, "reveal"):
        return f"expected a secret value, got {type(result).__name__}"
    return None if result.reveal() == expected else "revealed value differs"


def _check_equals(result: Any, expected: Any, ctx: StepContext) -> str | None:
    actual = to_jsonable(result)
    if _subset_equal(actual, expected):
        return None
    return f"expected {expected!r}, got {actual!r}"


def _check_null(result: Any, expected: Any, ctx: StepContext) -> str | None:
    is_null = result is None
    return None if is_null == bool(expected) else f"null={is_null}, expected null={expected}"


def _check_not_null(result: Any, expected: Any, ctx: StepContext) -> str | None:
    return _check_null(result, not expected, ctx)


def _check_true(result: Any, expected: Any, ctx: StepContext) -> str | None:
    return None if (result is True) == bool(expected) else f"expected true, got {result!r}"


def _check_false(result: Any, expected: Any, ctx: StepContext) -> str | None:
    return None if (result is False) == bool(expected) else f"expected false, got {result!r}"


def _contains(result: Any, expected: Any) -> bool:
    actual = to_jsonable(result)
    if isinstance(actual, str):
        return str(expected) in actual
    if isinstance(actual, dict):
        return expected in actual
    if isinstance(actual, list):
        return any(_subset_equal(item, expected) for item in actual)
    return False


def _check_contains(result: Any, expected: Any, ctx: StepContext) -> str | None:
    return None if _contains(result, expected) else f"result does not contain {expected!r}"


def _check_not_contains(result: Any, expected: Any, ctx: StepContext) -> str | None:
    return None if not _contains(result, expected) else f"result contains {expected!r}"


def _check_count(result: Any, expected: Any, ctx: StepContext) -> str | None:
    size = _size(result)
    return None if size == expected else f"expected count {expected}, got {size}"


def _check_min_count(result: Any, expected: Any, ctx: StepContext) -> str | None:
    size = _size(result)
    if size is not None and size >= expected:
        return None
    return f"expected at least {expected}, got {size}"


def _check_sorted(result: Any, expected: Any, ctx: StepContext) -> str | None:
    items = to_jsonable(result)
    if not isinstance(items, list):
        return "result is not a list"
    keys = [str(i.get("name")) if isinstance(i, dict) else str(i) for i in items]
    is_sorted = all(a <= b for a, b in itertools.pairwise(keys))
    return None if is_sorted == bool(expected) else f"sorted={is_sorted}, expected {expected}"


_TYPES: dict[str, Callable[[Any], bool]] = {
    "string": lambda v: isinstance(v, str),
    "number": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "boolean": lambda v: isinstance(v, bool),
    "object": lambda v: isinstance(v, dict),
    "array": lambda v: isinstance(v, list),
}


def _check_type(result: Any, expected: Any, ctx: StepContext) -> str | None:
    check = _TYPES.get(str(expected))
    if check is None:
        return f"unknown type {expected!r}"
    return (
        None if check(to_jsonable(result)) else f"expected {expected}, got {type(result).__name__}"
    )


def _check_string_form(result: Any, expected: Any, ctx: StepContext) -> str | None:
    forms = _forms(result)
    if "notContains" in expected and any(str(expected["notContains"]) in f for f in forms):
        return "string form leaks a forbidden value"
    if "contains" in expected and not any(str(expected["contains"]) in f for f in forms):
        return f"string form does not contain {expected['contains']!r}"
    return None


def _check_tree(result: Any, expected: Any, ctx: StepContext) -> str | None:
    doc = to_jsonable(result)
    spans = doc.get("spans") if isinstance(doc, dict) else doc
    if not isinstance(spans, list):
        return "result has no spans"
    by_id = {s.get("spanId"): s for s in spans if isinstance(s, dict)}
    children: dict[str, list[str]] = {}
    for s in by_id.values():
        parent = by_id.get(s.get("parentSpanId"))
        if parent is not None:
            children.setdefault(str(parent.get("name")), []).append(str(s.get("name")))
    for parent_name, names in expected.items():
        got = sorted(children.get(parent_name, []))
        if got != sorted(names):
            return f"children of {parent_name!r}: expected {sorted(names)}, got {got}"
    return None


for _name, _checker in {
    "reveal": _check_reveal,
    "equals": _check_equals,
    "null": _check_null,
    "notNull": _check_not_null,
    "true": _check_true,
    "false": _check_false,
    "contains": _check_contains,
    "notContains": _check_not_contains,
    "count": _check_count,
    "minCount": _check_min_count,
    "sorted": _check_sorted,
    "type": _check_type,
    "stringForm": _check_string_form,
    "tree": _check_tree,
}.items():
    register_expectation(_name, _checker)


# --------------------------------------------------------------------------- runner


def _random_id() -> str:
    return "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(8))


class ConformanceRunner:
    """Runs scenarios for the categories that have a factory.

    Args:
        factories: ``{category: factory(ScenarioContext) -> target}``.
        capabilities: what the target supports (``write``, ``delete``, ``versions``, ``query``,
            ``version`` …); scenarios/steps requiring anything else are skipped and reported.
        prefix: secrets name prefix; ``${run}`` is substituted (default
            ``grow-conformance/${run}/``).
        service_name: value of ``${serviceName}`` (tracing).
        scenarios_dir: defaults to :func:`find_scenarios_dir`.
        random_id: generates ``${run}`` (8 lowercase characters by default).
    """

    def __init__(
        self,
        factories: Mapping[str, Callable[[ScenarioContext], Any]],
        *,
        capabilities: Collection[str] = (),
        prefix: str | None = None,
        service_name: str | None = None,
        scenarios_dir: Path | str | None = None,
        random_id: Callable[[], str] = _random_id,
    ) -> None:
        self.factories = dict(factories)
        self.capabilities = set(capabilities)
        self.prefix = prefix if prefix is not None else "grow-conformance/${run}/"
        self.service_name = service_name
        self.scenarios_dir = scenarios_dir
        self.random_id = random_id

    def scenarios(self) -> list[dict[str, Any]]:
        return load_scenarios(self.scenarios_dir, self.factories)

    def run(self, scenarios: Iterable[Mapping[str, Any]] | None = None) -> ConformanceReport:
        report = ConformanceReport()
        for scenario in self.scenarios() if scenarios is None else scenarios:
            report.results.append(self.run_scenario(scenario))
        return report

    def run_scenario(self, scenario: Mapping[str, Any]) -> ScenarioResult:
        started = time.monotonic()
        result = self._run(scenario)
        result.duration_s = round(time.monotonic() - started, 3)
        return result

    def _run(self, scenario: Mapping[str, Any]) -> ScenarioResult:
        sid = str(scenario.get("id", "?"))
        category = str(scenario.get("category", "?"))
        result = ScenarioResult(sid, category, "passed")
        factory = self.factories.get(category)
        if factory is None:
            result.status, result.reason = "skipped", f"no factory for category {category!r}"
            return result
        missing = sorted(set(scenario.get("requires", [])) - self.capabilities)
        if missing:
            result.status, result.reason = "skipped", "missing capabilities: " + ", ".join(missing)
            return result
        ops = _OPS.get(category, {})
        run = self.random_id()
        prefix = self.prefix.replace("${run}", run)
        variables: dict[str, Any] = {"run": run, "prefix": prefix}
        if self.service_name is not None:
            variables["serviceName"] = self.service_name
        ctx = StepContext(scenario, None, variables)
        try:
            ctx.target = ctx.resolve(
                factory(ScenarioContext(scenario, run, prefix, self.service_name))
            )
            for index, step in enumerate(scenario.get("steps", [])):
                step_result = self._step(ctx, ops, index, step)
                result.steps.append(step_result)
                if step_result.status == "failed":
                    result.status = "failed"
                    result.reason = f"step {index} ({step_result.op}): {step_result.message}"
                    break
        except Exception as exc:  # noqa: BLE001 - reported as a failure
            result.status, result.reason = "failed", f"setup failed: {exc!r}"
        finally:
            teardown = _TEARDOWNS.get(category)
            if teardown is not None and ctx.target is not None:
                try:
                    ctx.resolve(teardown(ctx.target))
                except Exception as exc:  # noqa: BLE001 - reported as a failure
                    if result.status != "failed":
                        result.status, result.reason = "failed", f"teardown failed: {exc!r}"
            ctx.close()
        return result

    def _step(
        self, ctx: StepContext, ops: Mapping[str, OpHandler], index: int, step: Mapping[str, Any]
    ) -> StepResult:
        op = str(step.get("op"))
        missing = sorted(set(step.get("requires", [])) - self.capabilities)
        if missing:
            return StepResult(index, op, "skipped", "missing capabilities: " + ", ".join(missing))
        handler = ops.get(op)
        if handler is None:
            return StepResult(index, op, "failed", f"unknown op {op!r}")
        args = ctx.substitute(dict(step.get("args", {})))
        expect = ctx.substitute(dict(step.get("expect", {})))
        expected_error = expect.pop("error", None)
        if op not in _POLLED.get(str(ctx.scenario.get("category")), ()):
            return self._attempt(ctx, handler, index, op, step, args, expect, expected_error)
        timeout = float(args.get("timeoutMs", DEFAULT_POLL_TIMEOUT_MS)) / 1000.0
        interval = float(args.get("intervalMs", DEFAULT_POLL_INTERVAL_MS)) / 1000.0
        deadline = time.monotonic() + timeout
        while True:
            result = self._attempt(ctx, handler, index, op, step, args, expect, expected_error)
            remaining = deadline - time.monotonic()
            if result.status == "passed" or remaining <= 0:
                return result
            time.sleep(min(interval, remaining))

    def _attempt(
        self,
        ctx: StepContext,
        handler: OpHandler,
        index: int,
        op: str,
        step: Mapping[str, Any],
        args: dict[str, Any],
        expect: dict[str, Any],
        expected_error: Any,
    ) -> StepResult:
        try:
            value = ctx.resolve(handler(ctx, args))
        except ServiceError as err:
            if expected_error is None:
                return StepResult(index, op, "failed", f"raised {err.code.value}: {err.message}")
            if err.code != ErrorCode(expected_error):
                return StepResult(
                    index, op, "failed", f"expected error {expected_error}, got {err.code.value}"
                )
            return StepResult(index, op, "passed")
        except Exception as exc:  # noqa: BLE001 - reported as a failure
            return StepResult(index, op, "failed", f"raised {exc!r}")
        if expected_error is not None:
            return StepResult(index, op, "failed", f"expected error {expected_error}, none raised")
        if "save" in step:
            ctx.variables[str(step["save"])] = value
        for name, expected in expect.items():
            checker = _EXPECTATIONS.get(name)
            if checker is None:
                return StepResult(index, op, "failed", f"unknown expectation {name!r}")
            problem = checker(value, expected, ctx)
            if problem:
                return StepResult(index, op, "failed", f"{name}: {problem}")
        return StepResult(index, op, "passed")


# --------------------------------------------------------------------------- pytest helpers


def pytest_params(
    directory: Path | str | None = None, categories: Iterable[str] | None = None
) -> list[Any]:
    """``pytest.param`` objects (id = scenario id) for ``@pytest.mark.parametrize``."""
    import pytest  # noqa: PLC0415 - optional, test-time only

    return [pytest.param(s, id=str(s.get("id"))) for s in load_scenarios(directory, categories)]


def assert_scenario(runner: ConformanceRunner, scenario: Mapping[str, Any]) -> ScenarioResult:
    """Run one scenario inside a pytest test: skips on skip, fails with the reason."""
    import pytest  # noqa: PLC0415 - optional, test-time only

    result = runner.run_scenario(scenario)
    if result.status == "skipped":
        pytest.skip(f"{result.id}: {result.reason}")
    if result.status == "failed":
        pytest.fail(f"{result.id}: {result.reason}", pytrace=False)
    return result


def _core_health(ctx: StepContext, args: dict[str, Any]) -> Any:
    return ctx.target.health()


def _core_ping(ctx: StepContext, args: dict[str, Any]) -> Any:
    return ctx.target.ping()


def _core_server_version(ctx: StepContext, args: dict[str, Any]) -> Any:
    return ctx.target.server_version()


def _core_close(ctx: StepContext, args: dict[str, Any]) -> Any:
    return ctx.target.close()


def _core_teardown(target: Any) -> Any:
    return target.close()


register_ops(
    "core",
    {
        "health": _core_health,
        "ping": _core_ping,
        "serverVersion": _core_server_version,
        "close": _core_close,
    },
    teardown=_core_teardown,
)
